fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    let mut result = Vec::with_capacity(indices.len());
    for idx in indices {
        // Safe to index directly since we assume 0 <= idx < arr.len()
        result.push(arr[idx]);
    }
    result
}

